import React, { useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";

export default function Signup() {
  const [data, setData] = useState({
    name: "",
    email: "",
    password: "",
    role: "Member",
  });

  const navigate = useNavigate();

  const handleSignup = async () => {
    try {
      await axios.post(
        "http://localhost:9000/api/auth/signup",
        data
      );

      alert("Signup Successful");

      navigate("/");
   } catch (err) {
  console.log("FULL SIGNUP ERROR:", err);
  console.log("BACKEND ERROR:", err.response?.data);
  alert(err.response?.data?.message || err.message || "Signup Failed");
}
  };

  return (
    <div style={styles.container}>
      <h1>Signup</h1>

      <input
        style={styles.input}
        placeholder="Name"
        onChange={(e) =>
          setData({
            ...data,
            name: e.target.value,
          })
        }
      />

      <input
        style={styles.input}
        placeholder="Email"
        onChange={(e) =>
          setData({
            ...data,
            email: e.target.value,
          })
        }
      />

      <input
        style={styles.input}
        type="password"
        placeholder="Password"
        onChange={(e) =>
          setData({
            ...data,
            password: e.target.value,
          })
        }
      />

      <select
        style={styles.input}
        onChange={(e) =>
          setData({
            ...data,
            role: e.target.value,
          })
        }
      >
        <option>Member</option>
        <option>Admin</option>
      </select>

      <button
        style={styles.button}
        onClick={handleSignup}
      >
        Signup
      </button>

      <p>
        Already have account?
        <Link to="/">
          Login
        </Link>
      </p>
    </div>
  );
}

const styles = {
  container: {
    width: "350px",
    margin: "100px auto",
    padding: "30px",
    background: "white",
    borderRadius: "10px",
    boxShadow: "0px 0px 10px #ccc",
    textAlign: "center",
  },

  input: {
    width: "100%",
    padding: "10px",
    marginTop: "10px",
  },

  button: {
    width: "100%",
    padding: "10px",
    marginTop: "15px",
    background: "#4f46e5",
    color: "white",
    border: "none",
  },
};
